<script lang="ts">
  import { Schema } from 'effect'; import { onMount } from 'svelte'; import Page from '@/lib/components/dashboard/Page.svelte'; import { dashboardJson,jsonRequest } from '@/lib/components/dashboard/api'
  const Prefs=Schema.Struct({id:Schema.String,userId:Schema.String,mixReleaseEnabled:Schema.Boolean,promotionalEnabled:Schema.Boolean,systemEnabled:Schema.Boolean,globalUnsubscribe:Schema.Boolean,unsubscribeToken:Schema.NullOr(Schema.String),createdAt:Schema.String,updatedAt:Schema.String})
  let prefs=$state({mixReleaseEnabled:true,promotionalEnabled:true,systemEnabled:true,globalUnsubscribe:false}),message=$state('')
  onMount(async()=>{try{const p=await dashboardJson(Prefs,'/api/user/email-preferences');prefs={mixReleaseEnabled:p.mixReleaseEnabled,promotionalEnabled:p.promotionalEnabled,systemEnabled:p.systemEnabled,globalUnsubscribe:p.globalUnsubscribe}}catch{message='Could not load preferences.'}})
  async function save(){try{await dashboardJson(Prefs,'/api/user/email-preferences',jsonRequest('PATCH',prefs));message='Preferences saved.'}catch{message='Could not save preferences.'}}
</script>
<Page title="Email Notifications" description="Choose which emails you receive."><form class="max-w-2xl space-y-4 rounded border p-5" onsubmit={(e)=>{e.preventDefault();void save()}}>{#each [{key:'mixReleaseEnabled',label:'New mix and show updates'},{key:'promotionalEnabled',label:'Promotional emails'},{key:'systemEnabled',label:'System notifications'},{key:'globalUnsubscribe',label:'Unsubscribe from all non-essential email'}] as item}<label class="flex justify-between gap-4"><span>{item.label}</span><input type="checkbox" bind:checked={prefs[item.key as keyof typeof prefs]} /></label>{/each}<button class="rounded bg-foreground px-4 py-2 text-background">Save preferences</button>{#if message}<span class="ml-3" aria-live="polite">{message}</span>{/if}</form></Page>
